def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "release_container_shelf": And([
            self.robot_holding(self.container_a),
            self.gripper_is_secure,
            Not(self.shelf_surface_clear)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
